{
  "model": "deepseek-chat",
  "messages": [
    {
      "role": "system",
      "content": "你是专业的漫剧编剧。根据给定的世界观设定和故事文本，生成适合制作漫剧的中文剧本和分镜脚本。

输出要求：
- 严格输出 JSON 格式，不要包含 markdown 代码块标记
- scene 数量控制在 5-10 个
- 每个 scene 包含：num（分镜号）、description（画面描述，用于图片生成）、dialogue（台词/旁白）、duration_ms（时长毫秒）

输出 JSON 格式：
{
  "script_text": "完整剧本文字",
  "scenes": [
    {"num": 1, "description": "...", "dialogue": "...", "duration_ms": 5000},
    ...
  ]
}"
    },
    {
      "role": "user",
      "content": "=世界观设定：
{{ $json.world_setting }}

故事内容：
{{ $json.story_text }}

角色列表：
{{ JSON.stringify($json.characters) }}"
    }
  ],
  "temperature": 0.8,
  "max_tokens": 4096,
  "response_format": { "type": "json_object" }
}

parameters.jsCode:
// ==========================================
// Step 3: 解析 DeepSeek 返回的剧本 JSON
// 提取 script_text 和 scenes，构建回调 payload
// ==========================================

const items = $input.all();

for (const item of items) {
  // 解析 HTTP Request 节点返回的 body
  let body;
  try {
    body = JSON.parse(item.json.body || '{}');
  } catch (e) {
    throw new Error('无法解析 DeepSeek HTTP 响应: ' + e.message);
  }

  const content = body.choices?.[0]?.message?.content;
  if (!content) {
    throw new Error('DeepSeek 响应中未找到 choices[0].message.content');
  }

  // 尝试解析 DeepSeek 返回的 JSON（可能被包裹在 markdown 代码块中）
  let parsed;
  try {
    parsed = JSON.parse(content);
  } catch (e) {
    // 尝试提取被 ```json ... ``` 包裹的 JSON 块
    const match = content.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        parsed = JSON.parse(match[0]);
      } catch (e2) {
        throw new Error('无法解析 DeepSeek 返回的 JSON 内容');
      }
    } else {
      throw new Error('DeepSeek 返回内容中未找到 JSON 结构');
    }
  }

  // 验证必要字段
  if (!parsed.scenes || !Array.isArray(parsed.scenes)) {
    throw new Error('DeepSeek 返回的 JSON 缺少 scenes 数组');
  }

  // 构建回调 payload
  return {
    event: 'script_done',
    project_id: item.json.project_id || $json.project_id,
    episode_id: item.json.episode_id || $json.episode_id,
    data: {
      script_text: parsed.script_text || '',
      scene_count: parsed.scenes.length,
      scenes: parsed.scenes.map(s => ({
        num: s.num,
        description: s.description,
        dialogue: s.dialogue || '',
        duration_ms: s.duration_ms || 5000
      }))
    }
  };
}

// fallback
return { event: 'script_done', error: 'no items processed' };

// 解析即梦返回的图片 URL，回调 scene_image_done
const item = $input.first();
const imgResponse = JSON.parse(item.json.body || '{}');
const imageUrl = imgResponse.data?.[0]?.url || imgResponse.url || '';

return {
  event: 'scene_image_done',
  project_id: item.json.project_id,
  episode_id: item.json.episode_id,
  scene_num: item.json.num,
  data: {
    scene_num: item.json.num,
    image_url: imageUrl
  }
};
